"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[89631],{34352(e,n,i){i.r(n),i.d(n,{assets:()=>l,contentTitle:()=>u,default:()=>c,frontMatter:()=>a,metadata:()=>r,toc:()=>d});const r=JSON.parse('{"id":"learning/courses/practical-near-term-qc/introduction","title":"Introduction","description":"Eine Einf\xfchrung in einen Kurs \xfcber praktische Anwendungen des Quantencomputings.","source":"@site/i18n/de/docusaurus-plugin-content-docs/current/learning/courses/practical-near-term-qc/introduction.mdx","sourceDirName":"learning/courses/practical-near-term-qc","slug":"/learning/courses/practical-near-term-qc/introduction","permalink":"/learning/courses/practical-near-term-qc/introduction","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/practical-near-term-qc/introduction.mdx","tags":[],"version":"current","frontMatter":{"description":"Eine Einf\xfchrung in einen Kurs \xfcber praktische Anwendungen des Quantencomputings.","notebook_path":"learning/courses/practical-near-term-qc/introduction.ipynb","sidebar_label":"Introduction","title":"Introduction"},"sidebar":"tutorialsSidebar","previous":{"title":"Praktisches Quantencomputing der nahen Zukunft","permalink":"/learning/courses/practical-near-term-qc/"},"next":{"title":"\xdcbersicht","permalink":"/learning/courses/quantum-business-foundations/"}}');var t=i(74848),s=i(28453);const a={description:"Eine Einf\xfchrung in einen Kurs \xfcber praktische Anwendungen des Quantencomputings.",notebook_path:"learning/courses/practical-near-term-qc/introduction.ipynb",sidebar_label:"Introduction",title:"Introduction"},u="Einf\xfchrung in praxisnahes Quantencomputing der nahen Zukunft {#introduction-to-practical-near-term-quantum-computing}",l={},d=[{value:"Wof\xfcr Quantencomputer n\xfctzlich sein k\xf6nnten",id:"what-quantum-computers-might-be-useful-for",level:2},{value:"Quantennutzen und Quantenvorteil in der nahen Zukunft",id:"near-term-quantum-utility-and-advantage",level:2},{value:"Eine kurze Grundlage der Komplexit\xe4tstheorie",id:"a-brief-foundation-in-complexity-theory",level:2},{value:"Von der Komplexit\xe4tstheorie zu praktischen Belegen",id:"from-complexity-theory-to-practical-evidence",level:2},{value:"Anwendungsbereiche und Fallstudien des Kurses",id:"application-areas-and-course-case-studies",level:2},{value:"Hamilton-Simulation",id:"hamiltonian-simulation",level:3},{value:"Optimierung",id:"optimization",level:3},{value:"Quantum Machine Learning",id:"quantum-machine-learning",level:3},{value:"Partielle Differentialgleichungen",id:"partial-differential-equations",level:3},{value:"Fazit",id:"conclusion",level:2}];function h(e){const n={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:["\n",(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"introduction-to-practical-near-term-quantum-computing",children:"Einf\xfchrung in praxisnahes Quantencomputing der nahen Zukunft"})}),"\n",(0,t.jsx)(n.p,{children:"Seit Quantencomputer vor mehr als vier Jahrzehnten erstmals vorgeschlagen wurden, lautet die Frage: Wie weit k\xf6nnte dieser neue Ansatz die Grenzen des Rechnens verschieben? Die theoretische Informatik hat uns einige spannende Antworten geliefert. Quantencomputer k\xf6nnten gro\xdfe ganze Zahlen dramatisch schneller faktorisieren als die bekanntesten klassischen Methoden, die unstrukturierte Suche beschleunigen und Quantensysteme nat\xfcrlicher simulieren. Viele dieser Ideen setzten jedoch einen zuk\xfcnftigen, gro\xdfen, fehlertoleranten Quantencomputer voraus."}),"\n",(0,t.jsx)(n.p,{children:"Die Technologie hat noch nicht alle diese theoretischen Ziele erreicht, verbessert sich aber rasant. Forschende k\xf6nnen Quantenprozessoren heute nutzen, um reale wissenschaftliche und industrielle Probleme zu untersuchen. In diesem Kurs sammeln wir praktische Erfahrung mit einigen der vielversprechendsten Anwendungen. Wir sch\xe4tzen niederenergetische Eigenschaften eines komplexen Molek\xfclmodells ab, simulieren die Dynamik einer Gittereichtheorie und untersuchen, wie ein Portfolioproblem aus dem Finanzwesen auf einen Quantencomputer abgebildet werden kann. Au\xdferdem betrachten wir neuere Gebiete, in denen wir erst anfangen zu verstehen, was Quantencomputer leisten k\xf6nnten, darunter Quantum Machine Learning (QML) und Quantenans\xe4tze f\xfcr partielle Differentialgleichungen (PDEs)."}),"\n",(0,t.jsx)(n.p,{children:"Viele der Beispiele in diesem Kurs sind klein genug, dass ein klassischer Computer sie l\xf6sen kann. Das ist beabsichtigt. Das Ziel ist, dir greifbare Erfahrung mit dem gesamten Ablauf zu geben, einen Quantencomputer f\xfcr ein reales Problem einzusetzen. Einige Beispiele stehen f\xfcr Probleme, bei denen ein Quantenvorteil in deutlich gr\xf6\xdferem Ma\xdfstab entstehen k\xf6nnte. In anderen Beispielen verwenden wir eine vereinfachte Methode, damit Implementierungsdetails die zentrale Quantenidee nicht verdecken."}),"\n",(0,t.jsx)(n.p,{children:"Am Ende des Kurses solltest du einen \xdcberblick \xfcber die wichtigsten Quantenanwendungen haben und eine Intuition daf\xfcr, warum Quantencomputer in bestimmten Bereichen n\xfctzlich sein k\xf6nnten. Du lernst g\xe4ngige Techniken kennen, um Probleme auf Quantencomputern darzustellen, erf\xe4hrst, wie Quanten- und klassische Methoden zusammenarbeiten, und beginnst zu erkennen, welche Werkzeuge und Kompromisse f\xfcr unterschiedliche Problemarten wichtig sind."}),"\n",(0,t.jsx)(n.p,{children:"In dieser ersten Lektion behandeln wir einige grundlegende Konzepte und Begriffe, die dir helfen, Anwendungen des Quantencomputings auf hoher Ebene zu verstehen, und geben dir einen \xdcberblick \xfcber die wichtigsten Anwendungsbereiche, die die wissenschaftliche Gemeinschaft aktiv verfolgt."}),"\n",(0,t.jsx)(n.h2,{id:"what-quantum-computers-might-be-useful-for",children:"Wof\xfcr Quantencomputer n\xfctzlich sein k\xf6nnten"}),"\n",(0,t.jsx)(n.p,{children:"Quantencomputer werden oft als Konkurrenten klassischer Computer dargestellt, angemessener ist es jedoch, sie als spezialisierte Ressourcen innerhalb gr\xf6\xdferer klassischer Arbeitsabl\xe4ufe zu betrachten. Die entscheidende Frage ist dann, welche Teile einer Berechnung f\xfcr Quantenhardware besonders gut geeignet sind. Die intuitivste Antwort liefern Probleme, die bereits quantenmechanisch sind, etwa das Verhalten von Molek\xfclen, Materialien und Quantenfeldern. Ein Quantenprozessor kann Quantenzust\xe4nde direkt darstellen und manipulieren, w\xe4hrend die f\xfcr eine allgemeine klassische Beschreibung n\xf6tigen Ressourcen exponentiell mit der Systemgr\xf6\xdfe wachsen."}),"\n",(0,t.jsx)(n.p,{children:"Bei Problemen mit klassischen Ein- und Ausgaben ist die Lage subtiler, aber es gibt dennoch gute Gr\xfcnde, sie zu untersuchen. Optimierungsprobleme sind weit verbreitet und wirtschaftlich wichtig, sodass schon eine bescheidene Verbesserung der L\xf6sungsqualit\xe4t oder der Laufzeit wertvoll sein k\xf6nnte. Quantenalgorithmen k\xf6nnten au\xdferdem neue Wege bieten, komplizierte L\xf6sungsr\xe4ume zu erkunden oder die Struktur bestimmter Problemklassen auszunutzen. Quantum Machine Learning hat f\xfcr bestimmte Probleme mit klassischen Eingaben eine starke theoretische Motivation, darunter strukturierte Klassifikation und die Verarbeitung riesiger Datens\xe4tze. Ob sich diese Ergebnisse jedoch in einen praktischen Vorteil bei realen klassischen Daten \xfcbertragen lassen, bleibt eine offene Frage. Partielle Differentialgleichungen beschreiben viele wichtige Systeme in Wissenschaft, Technik und Finanzwesen, und Quantenalgorithmen k\xf6nnten die Skalierung bestimmter hochdimensionaler Simulationen und gro\xdfer Probleme der linearen Algebra verbessern."}),"\n",(0,t.jsx)(n.p,{children:"In allen drei Bereichen k\xf6nnen jedoch die Kosten f\xfcr die Vorbereitung klassischer Eingaben, die Ausf\xfchrung der Quantenberechnung und die Gewinnung einer n\xfctzlichen klassischen Antwort den Nutzen des Quantenschritts \xfcberwiegen. Diese praktischen Herausforderungen behalten wir im Blick, w\xe4hrend wir untersuchen, wie Quantenmethoden in jedem Bereich angewendet werden."}),"\n",(0,t.jsx)(n.h2,{id:"near-term-quantum-utility-and-advantage",children:"Quantennutzen und Quantenvorteil in der nahen Zukunft"}),"\n",(0,t.jsx)(n.p,{children:"In diesem Kurs geht es nicht speziell um Quantenvorteil, aber an einer Diskussion dar\xfcber f\xfchrt kein Weg vorbei. Die grundlegende Motivation hinter Quantenanwendungen ist, Quantenressourcen zu nutzen, um zu erweitern, was klassische Computer allein leisten k\xf6nnen: genauere Ergebnisse zu erzielen, L\xf6sungen schneller zu erreichen oder Probleme zu l\xf6sen, die sonst unzug\xe4nglich sind. Die folgenden verwandten Begriffe helfen uns, klar \xfcber den beobachteten Fortschritt zu sprechen:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Quantenbeschleunigung (Quantum Speedup):"})," Mit wachsender Problemgr\xf6\xdfe skaliert die ben\xf6tigte Zeit einer Quantenmethode g\xfcnstiger als die der besten relevanten klassischen Methode f\xfcr dieselbe Aufgabe."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Quantenvorteil:"})," Eine quantengest\xfctzte Berechnung \xfcbertrifft die besten relevanten klassischen Ans\xe4tze bei einer klar definierten Aufgabe und einer aussagekr\xe4ftigen Metrik. Statt eines einzelnen, dauerhaften Meilensteins ist der Quantenvorteil eine sich entwickelnde Grenze, die sich verschiebt, wenn sich sowohl Quanten- als auch klassische Methoden verbessern."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Quantennutzen (Quantum Utility):"})," Eine Quantenberechnung tr\xe4gt zu einem n\xfctzlichen wissenschaftlichen oder technischen Ergebnis bei. Sie arbeitet in einem Ma\xdfstab, einer Tiefe und einer Genauigkeit jenseits praktikabler klassischer Brute-Force-Simulation, ohne zwingend die beste klassische Methode zu \xfcbertreffen."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Near-Term-Algorithmus:"})," Ein Algorithmus, der f\xfcr aktuelle Quantenprozessoren entwickelt wurde, begrenzte Circuit-Tiefen nutzt und sich oft auf klassische Nachbearbeitung und Fehlerminderung statt auf vollst\xe4ndige Quantenfehlerkorrektur st\xfctzt."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Fehlertolerantes Quantencomputing:"})," In Zukunft wird Quantencomputing Quantenfehlerkorrektur nutzen, um logische Qubits w\xe4hrend einer gesamten Berechnung zu sch\xfctzen. Liegen die physikalischen Fehlerraten unterhalb der Fehlertoleranzschwelle, k\xf6nnen zus\xe4tzliche Fehlerkorrektur-Ressourcen logische Fehler auf das Niveau senken, das lange, zuverl\xe4ssige Berechnungen erfordern. Fehlertoleranz macht deutlich tiefere Algorithmen m\xf6glich, einschlie\xdflich gro\xdfskaliger Implementierungen des Shor-Algorithmus."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Fr\xfche Fehlertoleranz:"})," Fehlertoleranz bedeutet, dass Fehler unterdr\xfcckt, nicht aber vollst\xe4ndig beseitigt werden. In fr\xfchen fehlertoleranten Systemen m\xfcssen verbleibende logische Fehler weiterhin ber\xfccksichtigt werden, und die Tiefe zuverl\xe4ssiger Circuits bleibt begrenzt."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Heuristischer Algorithmus:"})," Eine Methode, die in der Praxis eine gute L\xf6sung finden soll, ohne die optimale Antwort oder eine bestimmte Laufzeit zu garantieren."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.h2,{id:"a-brief-foundation-in-complexity-theory",children:"Eine kurze Grundlage der Komplexit\xe4tstheorie"}),"\n",(0,t.jsx)(n.p,{children:"In einigen Anwendungsbereichen haben wir einen starken theoretischen Grund zu erwarten, dass ein Quantencomputer einen Vorteil haben k\xf6nnte. Um zu verstehen, woher diese Zuversicht kommt, brauchen wir ein wenig Vokabular aus der Komplexit\xe4tstheorie."}),"\n",(0,t.jsx)(n.p,{children:"Die Komplexit\xe4tstheorie untersucht, wie die zur L\xf6sung eines Problems n\xf6tigen Ressourcen wachsen, wenn das Problem gr\xf6\xdfer wird. Sie gibt uns eine n\xfctzliche Landkarte daf\xfcr, wo eine Quantenbeschleunigung m\xf6glich sein k\xf6nnte. Einige Begriffe sind f\xfcr diesen Kurs besonders wichtig:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"P:"})," Probleme, die ein klassischer Computer effizient l\xf6sen kann, d. h. die ben\xf6tigten Ressourcen wachsen polynomiell mit der Problemgr\xf6\xdfe."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"NP:"})," Probleme, bei denen sich eine vorgeschlagene L\xf6sung effizient \xfcberpr\xfcfen l\xe4sst, auch wenn das Finden dieser L\xf6sung sehr schwierig sein kann."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"NP-schwer:"})," Probleme, die mindestens so schwer sind wie jedes Problem in NP. Ein NP-schweres Problem geh\xf6rt nicht notwendigerweise zu NP. Viele Optimierungsprobleme sind NP-schwer."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"NP-vollst\xe4ndig:"})," Probleme, die sowohl NP-schwer sind als auch in NP liegen. Dies sind die schwersten Entscheidungsprobleme innerhalb von NP."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"BQP:"})," Probleme, die ein Quantencomputer effizient mit beschr\xe4nkter Fehlerwahrscheinlichkeit l\xf6sen kann."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Einige Beziehungen zwischen diesen Kategorien sind bekannt. P ist sowohl in NP als auch in BQP enthalten, weil ein Problem, das auf einem klassischen Computer effizient gel\xf6st werden kann, auch klassisch \xfcberpr\xfcft und auf einem Quantencomputer gel\xf6st werden kann. Andere Beziehungen sind weiterhin offen. Wir wissen nicht, ob P gleich NP ist oder ob NP in BQP enthalten ist. Forschende glauben jedoch allgemein, dass P kleiner ist als NP und BQP und dass Quantencomputer nicht jedes NP-vollst\xe4ndige Problem effizient l\xf6sen k\xf6nnen. Einfach gesagt: Ein Quantencomputer ist keine Zauberkiste, die jedes schwere Problem sofort l\xf6st."}),"\n",(0,t.jsx)(n.p,{children:"Die st\xe4rksten komplexit\xe4tsbasierten Argumente f\xfcr Quantencomputing gelten f\xfcr bestimmte Problemarten. Der Shor-Algorithmus skaliert dramatisch besser als die bekanntesten klassischen Algorithmen f\xfcr Faktorisierung und diskrete Logarithmen, obwohl nicht bewiesen ist, dass die Faktorisierung au\xdferhalb von P liegt. Auch die allgemeine Quantensimulation hat ein starkes theoretisches Fundament. Einige Quantensimulationsprobleme sind BQP-vollst\xe4ndig, was bedeutet, dass ihre effiziente klassische L\xf6sung darauf hinausliefe, jede Quantenberechnung effizient zu simulieren. Eine solche effiziente klassische Simulation ist h\xf6chst unplausibel, und das ist ein Grund, warum die Quanten-Hamilton-Simulation als so vielversprechender Anwendungsbereich gilt."}),"\n",(0,t.jsx)(n.p,{children:"Einige hochdimensionale PDEs lassen sich auf BQP-vollst\xe4ndige Probleme linearer Gleichungssysteme zur\xfcckf\xfchren, was uns einen starken Grund gibt, eine Quantenbeschleunigung zu erwarten, wenn Ein- und Ausgaben effizient behandelt werden k\xf6nnen. QML hat \xe4hnliche Beispiele: Einige Aufgaben mit Quantendaten sind BQP-vollst\xe4ndig, und einige Quantenmodelle k\xf6nnen Stichproben erzeugen, die klassisch schwer zu reproduzieren sind."}),"\n",(0,t.jsx)(n.p,{children:"Bei der Optimierung ist die Lage weniger eindeutig. Es wird nicht erwartet, dass Quantencomputer beliebige NP-schwere Probleme effizient l\xf6sen, aber sie k\xf6nnten dennoch bei strukturierten Problemen, bestimmten Instanzen oder einzelnen Schritten eines Optimierungs-Workflows helfen. Der Grover-Algorithmus etwa liefert eine quadratische Beschleunigung bei der unstrukturierten Suche. Das ist eine bedeutsame Verbesserung, auch wenn die Quadratwurzel eines astronomisch gro\xdfen Suchraums immer noch astronomisch sein kann."}),"\n",(0,t.jsx)(n.h2,{id:"from-complexity-theory-to-practical-evidence",children:"Von der Komplexit\xe4tstheorie zu praktischen Belegen"}),"\n",(0,t.jsx)(n.p,{children:"Die Komplexit\xe4tstheorie kann uns sagen, wo eine Quantenbeschleunigung m\xf6glich sein k\xf6nnte, aber meist nicht, wie sich eine Methode bei einem bestimmten Problem oder auf einem bestimmten Quantencomputer verh\xe4lt. Viele der auf aktueller Hardware verwendeten Methoden sind heuristisch. Sie sind darauf ausgelegt, in der Praxis gute Antworten zu finden, garantieren aber weder die bestm\xf6gliche Antwort noch eine bestimmte Laufzeit."}),"\n",(0,t.jsx)(n.p,{children:"Heuristiken sind nicht auf das Quantencomputing beschr\xe4nkt, und eine Methode heuristisch zu nennen bedeutet nicht, dass sie unzuverl\xe4ssig oder unwissenschaftlich ist. Klassische Optimierung, maschinelles Lernen und Computerchemie st\xfctzen sich allesamt stark auf Heuristiken, wenn eine exakte L\xf6sung zu teuer w\xe4re. Eine Quantenheuristik k\xf6nnte einen neuen Weg bieten, einen L\xf6sungsraum zu erkunden, n\xfctzliche Zust\xe4nde vorzubereiten oder vielversprechende Kandidaten zu identifizieren. Ob sie gut funktioniert, ist eine empirische Frage: Wir m\xfcssen sie ausf\xfchren und das Ergebnis messen."}),"\n",(0,t.jsx)(n.p,{children:"Da Heuristiken keine Leistungsgarantien mitbringen, bewerten wir sie anhand einer klaren Erfolgsmetrik, starker klassischer Vergleichsmethoden und Tests \xfcber verschiedene Problemgr\xf6\xdfen hinweg. So erkennen wir, wo eine Methode gut funktioniert und wie sich ihre Leistung mit wachsender Problemgr\xf6\xdfe \xe4ndert."}),"\n",(0,t.jsx)(n.h2,{id:"application-areas-and-course-case-studies",children:"Anwendungsbereiche und Fallstudien des Kurses"}),"\n",(0,t.jsx)(n.p,{children:"Wir gliedern den Kurs in vier breite Anwendungsbereiche. Sie decken nicht jede m\xf6gliche Nutzung eines Quantencomputers ab, bieten aber eine n\xfctzliche M\xf6glichkeit zu vergleichen, wo die st\xe4rksten Argumente liegen und wo die offenen Fragen sind."}),"\n",(0,t.jsx)(n.h3,{id:"hamiltonian-simulation",children:"Hamilton-Simulation"}),"\n",(0,t.jsx)(n.p,{children:"Die Hamilton-Simulation umfasst die Absch\xe4tzung von Energien, die Untersuchung chemischer und materialbezogener Eigenschaften und die Modellierung, wie sich Quantensysteme zeitlich ver\xe4ndern. Sie reicht \xfcber Chemie, Materialwissenschaft, Physik der kondensierten Materie sowie Hochenergie- und Kernphysik. Unsere Fallstudien untersuchen ein stark korreliertes Eisen-Schwefel-Modell mit stichprobenbasierter Quantendiagonalisierung und simulieren Hadronendynamik mit einer symmetriebewussten Gitterdarstellung. Dies sind zwei Beispiele aus einem viel gr\xf6\xdferen Feld, zu dem auch Reaktionsmechanismen, magnetische Materialien und andere Vielteilchendynamiken geh\xf6ren."}),"\n",(0,t.jsx)(n.h3,{id:"optimization",children:"Optimierung"}),"\n",(0,t.jsx)(n.p,{children:"Optimierung taucht \xfcberall auf, von Finanzwesen und Logistik bis zu Terminplanung und Energiesystemen. Es ist auch ein Bereich, in dem sich ein Vorteil schwer nachweisen l\xe4sst, weil klassische L\xf6ser \xe4u\xdferst leistungsf\xe4hig sind und Quantenabbildungen kostspieligen Mehraufwand verursachen k\xf6nnen. Unsere Fallstudie nutzt die Portfolioauswahl, um zu untersuchen, wie ein Optimierungsproblem dargestellt, ausgef\xfchrt und bewertet wird, ohne anzunehmen, dass ein Quantencomputer automatisch das exakte Optimum findet."}),"\n",(0,t.jsx)(n.h3,{id:"quantum-machine-learning",children:"Quantum Machine Learning"}),"\n",(0,t.jsx)(n.p,{children:"Quantum Machine Learning fragt, ob Quanten-Circuits oder Quantendaten eine Lernaufgabe verbessern k\xf6nnen. Wichtige Fragen betreffen die Datenkodierung, die Trainingskosten, die Generalisierung und den Vergleich mit starken klassischen Modellen."}),"\n",(0,t.jsx)(n.h3,{id:"partial-differential-equations",children:"Partielle Differentialgleichungen"}),"\n",(0,t.jsx)(n.p,{children:"Partielle Differentialgleichungen beschreiben Systeme wie Str\xf6mungen, W\xe4rme und Wellen. Quantenalgorithmen k\xf6nnten Teile einiger PDE-Workflows beschleunigen, aber die Datenvorbereitung und die Gewinnung einer n\xfctzlichen klassischen Antwort k\xf6nnen erhebliche Kosten verursachen. Die konkrete Fallstudie befindet sich noch in Entwicklung."}),"\n",(0,t.jsx)(n.p,{children:"In den folgenden Lektionen stellen wir in jedem Bereich dieselben Grundfragen: Was ist das Problem, warum k\xf6nnte Quantencomputing helfen, was sind die Grenzen und was zeigen die Belege tats\xe4chlich? Wir beginnen mit der Hamilton-Simulation, bei der das Problem selbst quantenmechanisch ist."}),"\n",(0,t.jsx)(n.h2,{id:"conclusion",children:"Fazit"}),"\n",(0,t.jsx)(n.p,{children:"Wir haben viel Stoff behandelt, aber die Kernidee ist einfach: Quantencomputer sind spezialisierte Werkzeuge, und ihr Wert h\xe4ngt davon ab, die richtige Quantenmethode f\xfcr das richtige Problem oder den richtigen Teil eines gr\xf6\xdferen Problems einzusetzen. Die Hamilton-Simulation hat das klarste theoretische Fundament, die Optimierung verf\xfcgt \xfcber eine ausgereifte Menge heuristischer Methoden und Benchmarks, und QML und PDEs bieten vielversprechende Richtungen, die sich noch entwickeln."}),"\n",(0,t.jsx)(n.p,{children:"In den folgenden Lektionen gehen wir von diesem breiten \xdcberblick zu praktischen Beispielen \xfcber. F\xfcr jede Anwendung fragen wir, welches Problem wir l\xf6sen wollen, welche Rolle der Quantencomputer spielt, wie das Ergebnis interpretiert wird und was wir daraus lernen k\xf6nnen. Das Ziel ist, deine Intuition daf\xfcr aufzubauen, wo Quantencomputing helfen k\xf6nnte und was n\xf6tig ist, um eine vielversprechende Idee in eine echte Berechnung zu verwandeln."}),"\n"]})}function c(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(h,{...e})}):h(e)}},28453(e,n,i){i.d(n,{R:()=>a,x:()=>u});var r=i(96540);const t={},s=r.createContext(t);function a(e){const n=r.useContext(s);return r.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function u(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),r.createElement(s.Provider,{value:n},e.children)}}}]);